 ones=['','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
 tens=['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan']
 mon=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
 sf=['dır','dir','dir','tür','tür','tir','dır','dir','dir','dur']
 nm=['','bin','milyon','milyar','trilyon']
 def grp(g):
  p=[]
  if g//100:
   p.append('yüz' if g//100==1 else ones[g//100]+' yüz')
  if g//10%10:
   p.append(tens[g//10%10])
  if g%10:
   p.append(ones[g%10])
  return ' '.join(p)
 def words(n):
  if n==0:
   return 'sıfır'
  gs=[]
  while n>0:
   gs.append(n%1000)
   n=n//1000
  out=[]
  for i in range(len(gs)-1,-1,-1):
   g=gs[i]
   if g==0:
    continue
   if i==1 and g==1:
    out.append('bin')
   else:
    out.append(grp(g)+(' '+nm[i] if i else ''))
  return ' '.join(out)
 names=dict(TL=('lira','kuruş','Türk Lirası'),USD=('dolar','sent','dolar'),EUR=('euro','sent','euro'),GBP=('İngiliz Sterlini','peni','İngiliz Sterlini'))
 def M(x,c):
  v=int(round(abs(float(x))*100))
  a=v//100
  k=v%100
  n=names[c]
  if k==0:
   return words(a)+' '+n[2]
  if a==0:
   return words(k)+' '+n[1]
  return words(a)+' '+n[0]+' '+words(k)+' '+n[1]
 def sp(s):
  d,m,y=str(s).split('.')
  return str(int(d))+' '+mon[int(m)-1]+' '+y
 def dt(s):
  d,m,y=str(s).split('.')
  return datetime.date(int(y),int(m),int(d))
