     else:
      s=c[2]+' borcunuz '+M(sd,cc)+', ödenmesi gereken minimum tutar '+M(mn,cc)+', kalan toplam borcunuz '+M(rem,cc)+', kalan minimum ödeme tutarınız '+M(rm,cc)+'.'
